const input = $input.first().json;

// Debug complet pour comprendre la structure
console.log('=== WORKER DEBUG ===');
console.log('input keys:', Object.keys(input));
console.log('input.body type:', typeof input.body);
if (input.body) {
  console.log('input.body keys:', Object.keys(input.body));
  console.log('input.body.segments?:', Array.isArray(input.body.segments) ? input.body.segments.length : 'not array');
}

// Chercher les segments dans toutes les structures possibles
let segments = [];
let body = input;

// Structure 1: body.segments (webhook standard)
if (input.body && Array.isArray(input.body.segments)) {
  segments = input.body.segments;
  body = input.body;
  console.log('Found segments in input.body.segments:', segments.length);
}
// Structure 2: segments direct (données passées directement)
else if (Array.isArray(input.segments)) {
  segments = input.segments;
  console.log('Found segments in input.segments:', segments.length);
}
// Structure 3: body est une string JSON
else if (input.body && typeof input.body === 'string') {
  try {
    const parsed = JSON.parse(input.body);
    if (Array.isArray(parsed.segments)) {
      segments = parsed.segments;
      body = parsed;
      console.log('Found segments in parsed body string:', segments.length);
    }
  } catch(e) {
    console.log('Failed to parse body as JSON:', e.message);
  }
}

console.log('Final segments count:', segments.length);
console.log('=== END DEBUG ===');

// Stocker les données pour le traitement async
return [{
  json: {
    jobId: body.job_id || input.job_id,
    traite: body.traite || input.traite,
    page: body.page || input.page,
    mode: body.mode || input.mode || 'premium',
    targetLanguage: body.target_language || input.target_language || 'fr',
    apiKey: body.api_key || input.api_key,
    openaiApiKey: body.openai_api_key || input.openai_api_key,
    sourceTextId: body.source_text_id || input.source_text_id,
    reference: body.reference || input.reference,
    segments: segments,
    requestId: body.request_id || input.request_id,
    _debug: {
      inputKeys: Object.keys(input),
      hasBody: !!input.body,
      bodyType: typeof input.body,
      bodyKeys: input.body ? Object.keys(input.body) : [],
      segmentsLength: segments.length
    }
  }
}];

// Passer les données originales
const prevData = $('Parse Input').first().json;
return [{ json: prevData }];

// Convertir les segments en items pour la boucle
const input = $input.first().json;

const items = input.segments.map((segment, index) => ({
  json: {
    segmentIndex: index,
    segmentText: segment,
    totalSegments: input.segments.length,
    jobId: input.jobId,
    traite: input.traite,
    page: input.page,
    mode: input.mode,
    targetLanguage: input.targetLanguage,
    apiKey: input.apiKey,
    openaiApiKey: input.openaiApiKey,
    sourceTextId: input.sourceTextId,
    reference: input.reference,
    requestId: input.requestId
  }
}));

return items;

